--- /dev/null
+++ b/src/features/agenda.js
@@ -0,0 +1,17 @@
+import { createEventCard } from './event-card.js';
+
+// Pairs each event with its card, ordered by start time; ties keep input order.
+export function sortByStart(events) {
+  return events
+    .map((event) => ({
+      event,
+      card: createEventCard(event),
+      time: new Date(event.startsAt).getTime(),
+    }))
+    .sort((a, b) => a.time - b.time)
+    .map(({ event, card }) => ({ event, card }));
+}
+
+export function buildAgenda(events) {
+  return sortByStart(events).map(({ card }) => card);
+}

